package com.alsafa.native4.core;
import android.database.sqlite.SQLiteDatabase;
/** V17: auditable online-order shipping state and order-specific expenses. */
public final class CoreSchemaV17{private CoreSchemaV17(){}public static void create(SQLiteDatabase db){db.execSQL("CREATE TABLE IF NOT EXISTS online_order_expenses(expense_id TEXT PRIMARY KEY,settlement_id TEXT NOT NULL,expense_type TEXT NOT NULL,amount REAL NOT NULL,currency TEXT NOT NULL,paid_by TEXT NOT NULL,account TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL)");db.execSQL("CREATE INDEX IF NOT EXISTS idx_online_expenses_settlement ON online_order_expenses(settlement_id,created_at)");db.execSQL("CREATE TABLE IF NOT EXISTS online_shipping_events(event_id TEXT PRIMARY KEY,settlement_id TEXT NOT NULL,shipping_amount REAL NOT NULL,currency TEXT NOT NULL,responsibility TEXT NOT NULL,paid_status TEXT NOT NULL,paid_by TEXT NOT NULL,account TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL)");db.execSQL("CREATE INDEX IF NOT EXISTS idx_online_shipping_settlement ON online_shipping_events(settlement_id,created_at)");}}
